/**
 * Parity with the backend: reads ../spec/fixtures/model_vectors.json (spec v2, generated by the
 * backend) and checks the TypeScript math against it (rel 1e-6, ovl/err 1e-4). Skips when the
 * fixture is missing or is not version 2.
 */
import { existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { inverse, ladder, pairRow, pairRows, recover } from './analysis'
import { compileExpr } from './expr'
import { compileModel } from './model'
import { defaultSeries } from './presets'
import { kForError, ruleError } from './rule'
import { simulate } from './experiment'
import type { Series } from './types'

const FIXTURE = resolve(process.cwd(), '../spec/fixtures/model_vectors.json')
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = any
let fx: Json = null
let why = ''
if (!existsSync(FIXTURE)) why = `fixture not found at ${FIXTURE}`
else {
  try {
    fx = JSON.parse(readFileSync(FIXTURE, 'utf8'))
    if (fx.version !== 2) {
      why = `fixture version is ${String(fx.version)}, expected 2`
      fx = null
    }
  } catch (e) {
    why = `fixture unreadable: ${String(e)}`
  }
}
if (!fx) console.warn(`[parity] skipped: ${why}`)

function close(got: number, want: number | null, label: string, rel = 1e-6, abs = 1e-9) {
  if (want === null || want === undefined) {
    expect(Number.isFinite(got) ? got : null, `${label}: expected null`).toBeNull()
    return
  }
  expect(Number.isFinite(got), `${label}: got ${got}, want ${want}`).toBe(true)
  expect(Math.abs(got - want), `${label}: got ${got}, want ${want}`).toBeLessThanOrEqual(Math.max(abs, rel * Math.abs(want)))
}

const suite = fx ? describe : describe.skip
suite(`parity with backend fixtures${fx ? '' : ` (${why})`}`, () => {
  for (const cs of fx?.cases ?? []) {
    it(`case ${cs.name}`, () => {
      const s: Series = { ...defaultSeries(), ...cs.series }
      const m = compileModel(s)
      cs.grid.forEach((c: number, i: number) => {
        close(m.mean(c), cs.mean[i], `mean[${i}]`)
        close(m.sd(c), cs.sd[i], `sd[${i}]`)
      })
      if (cs.rows) {
        const rows = pairRows(m, m.levels, s.metric, s.kTarget)
        expect(rows.length).toBe(cs.rows.length)
        cs.rows.forEach((w: Json, i: number) => {
          for (const k of ['c1', 'c2', 'mu1', 'mu2', 'sd1', 'sd2', 'dmu', 'dsum', 'ssmd', 'zprime'] as const)
            if (k in w) close(rows[i][k], w[k], `rows[${i}].${k}`)
          for (const k of ['ovl', 'err'] as const) if (k in w) close(rows[i][k], w[k], `rows[${i}].${k}`, 1e-4, 1e-9)
          if ('pass' in w) expect(rows[i].pass, `rows[${i}].pass`).toBe(w.pass)
        })
      }
      for (const [i, lw] of (cs.ladder ?? []).entries()) {
        const got = ladder(m, lw.metric, lw.k, lw.sig)
        expect(got.length, `ladder[${i}] ${lw.metric} k=${lw.k} sig=${lw.sig}: length`).toBe(lw.levels.length)
        lw.levels.forEach((want: number, j: number) => close(got[j], want, `ladder[${i}][${j}]`))
      }
      for (const [i, w] of (cs.measure ?? []).entries()) {
        const row = pairRow(m, w.c1, w.c2, w.metric, w.k)
        for (const k of ['c1', 'c2', 'mu1', 'mu2', 'sd1', 'sd2', 'dmu', 'dsum', 'ssmd', 'zprime'] as const) close(row[k], w[k], `measure[${i}].${k}`)
        for (const k of ['ovl', 'err'] as const) close(row[k], w[k], `measure[${i}].${k}`, 1e-4, 1e-9)
        expect(row.pass, `measure[${i}].pass`).toBe(w.pass)
        const steps = ladder({ mean: m.mean, sd: m.sd, cMax: Math.max(w.c1, w.c2) }, w.metric, w.k, 0, 200, Math.min(w.c1, w.c2)).length - 1
        expect(steps, `measure[${i}].stepsBetween`).toBe(w.stepsBetween)
      }
      for (const [i, w] of (cs.recover ?? []).entries()) {
        const got = recover(m, w.signal, w.conf)
        for (const k of ['c', 'lo', 'hi'] as const) {
          if (w[k] === null) expect(got[k], `recover[${i}].${k}`).toBeNull()
          else close(got[k] as number, w[k], `recover[${i}].${k}`)
        }
        expect([got.loOpen, got.hiOpen], `recover[${i}] open ends`).toEqual([w.loOpen, w.hiOpen])
      }
      if (cs.inverse) {
        cs.inverse.signals.forEach((S: number, i: number) => {
          const got = inverse(m, S)
          const want = cs.inverse.c[i]
          if (want === null) expect(got, `inverse[${i}]`).toBeNull()
          else close(got as number, want, `inverse[${i}]`)
        })
      }
    })
  }
  for (const [i, sc] of (fx?.simulate ?? []).entries()) {
    it(`simulate ${i}`, () => {
      const m = compileModel({ ...defaultSeries(), ...(sc.series as Partial<Series>) } as Series)
      const a = sc.args
      let concs = a.concs
      let n = a.n
      if (a.measuredN) {
        concs = sc.result.concs
        n = sc.result.n
      }
      const got = simulate(m, { concs, n, runs: a.runs, seed: a.seed, metric: a.metric ?? sc.result.metric, k: a.k ?? sc.result.k, conf: a.conf })
      const want = sc.result
      expect(got.concs).toEqual(want.concs)
      want.first.levels.forEach((l: Json, j: number) => l.ys.forEach((y: number, q: number) => close(got.first.levels[j].ys[q], y, `first.levels[${j}].ys[${q}]`, 1e-9)))
      want.pairs.forEach((pw: Json, j: number) => {
        expect(got.pairs[j].pPass, `pairs[${j}].pPass`).toBe(pw.pPass)
        expect(got.pairs[j].pSig, `pairs[${j}].pSig`).toBe(pw.pSig)
        for (const key of ['lo', 'med', 'hi'] as const) close(got.pairs[j][key] as number, pw[key], `pairs[${j}].${key}`, 1e-9)
      })
      want.first.rows.forEach((r: Json, j: number) => close(got.first.rows[j].p, r.p, `first.rows[${j}].p`, 1e-8, 1e-12))
      expect(got.resolvedPairs.hist).toEqual(want.resolvedPairs.hist)
    })
  }
  for (const [i, rc] of (fx?.ruleCases ?? []).entries()) {
    it(`rule ${i}: ${rc.metric} k=${rc.k} error=${rc.error}`, () => {
      if (rc.error === 0 || rc.error === 0.5) expect(ruleError(rc.metric, rc.k)).toBe(rc.error)
      else close(ruleError(rc.metric, rc.k), rc.error, 'error')
      const k = kForError(rc.metric, rc.error)
      if (rc.error > 0 && rc.error < 0.5 && Math.abs(rc.k) < 1e6) close(k as number, rc.k, 'k')
    })
  }
  for (const [i, ec] of (fx?.exprCases ?? []).entries()) {
    it(`expr ${i}: ${ec.expr}`, () => {
      const r = compileExpr(ec.expr, ec.variable)
      expect(r.ok).toBe(ec.ok)
      if (!r.ok && ec.error_pos !== undefined) expect(r.pos).toBe(ec.error_pos)
      if (r.ok && ec.values) ec.values.x.forEach((x: number, j: number) => close(r.fn(x), ec.values.y[j], `expr(${x})`))
    })
  }
})
